// ── LUNCH ADAPTER (P4) ────────────────────────────────────────────────────────
// Canonical meal cards that live in another section but should ALSO appear on the
// Lunch shelf, in place of a thin duplicate. {id, cat} — cat = which Lunch pill it
// sits under. Render-side ONLY: the source array is never mutated (the injected card
// is a shallow copy carrying the Lunch cat); it opens its own full recipe and
// openMealRecipe / toggleMealPlan resolve it across sections (see fallbacks above).
// NOTE: of the 18 ⚑DUP lunch cards, only Shakshuka has a genuine fuller canonical
// (bf-shakshuka, 5 versions) — the rest have no fuller same-family card to promote,
// so they are left as-is until a canonical is built. Add a line here when one is.
var LUNCH_ADAPTER_INJECT = [
  { id:'bf-shakshuka', cat:'quick' }
];
function _findMealCardRaw(id){
  var arrs = [
    typeof BREAKFAST_RECIPES!=='undefined'?BREAKFAST_RECIPES:[],
    typeof LIGHTLUNCH_RECIPES!=='undefined'?LIGHTLUNCH_RECIPES:[],
    typeof SUPPER_RECIPES!=='undefined'?SUPPER_RECIPES:[],
    typeof BAKES_RECIPES!=='undefined'?BAKES_RECIPES:[],
    typeof SIDES_BASICS_RECIPES!=='undefined'?SIDES_BASICS_RECIPES:[]
  ];
  for(var a=0;a<arrs.length;a++){ var f=(arrs[a]||[]).find(function(x){return x&&x.id===id;}); if(f) return f; }
  return null;
}
function lunchInject(recipes){
  (LUNCH_ADAPTER_INJECT||[]).forEach(function(inj){
    if(recipes.some(function(x){return x.id===inj.id;})) return;   // already on the shelf
    var c = _findMealCardRaw(inj.id);
    if(c) recipes.push(Object.assign({}, c, {cat: inj.cat}));      // copy, carrying the Lunch cat
  });
  return recipes;
}

function mealSectionHTML(sectionKey){
  const configs = {
    breakfast:  {title:"Breakfast",         emoji:"🍳", color:"#d0a020", bg:"#181008", border:"#3a2010", recipes:typeof BREAKFAST_RECIPES!=='undefined'?BREAKFAST_RECIPES:[],  sub:"Morning meals · Start your day right", cats:[{id:"eggs",e:"🍳",l:"Eggs"},{id:"fryups",e:"🥓",l:"Fry-Ups"},{id:"toast",e:"🍞",l:"Toast"},{id:"pancakes",e:"🥞",l:"Pancakes & Waffles"},{id:"oats",e:"🥣",l:"Oats & Porridge"},{id:"baked",e:"🧁",l:"Baked"},{id:"smoothies",e:"🥤",l:"Smoothies & Bowls"}]},
    lightlunch: {title:"Light Lunch",       emoji:"🥗", color:"#30a070", bg:"#081810", border:"#1a4025", recipes:typeof LIGHTLUNCH_RECIPES!=='undefined'?LIGHTLUNCH_RECIPES:[],sub:"Salads · Wraps · Soups · Quick meals", cats:[{id:'salads',e:'🥗',l:'Salads & Bowls'},{id:'handhelds',e:'🥪',l:'Sandwiches & Wraps'},{id:'soups',e:'🍲',l:'Soups'},{id:'savbakes',e:'🥧',l:'Savoury Bakes'},{id:'quick',e:'⚡',l:'Quick & Light'}]},
    supper:     {title:"Supper",            emoji:"🍽️", color:"#6080d0", bg:"#080f18", border:"#1a2840", recipes:typeof SUPPER_RECIPES!=='undefined'?SUPPER_RECIPES:[],        sub:"Evening meals · Family dinners", cats:[{id:'plates',e:'🍳',l:'Homestyle Plates'},{id:'pastapizza',e:'🍝',l:'Pasta & Pizza'},{id:'stewscurries',e:'🍛',l:'Stews, Curries & One-Pots'},{id:'ovenbakes',e:'🥧',l:'Oven Bakes & Roasts'},{id:'friedgrilled',e:'🍔',l:'Fried & Grilled'}]},
    bakes:      {title:"Bakes & Cakes",     emoji:"🧁", color:"#d06080", bg:"#180810", border:"#401020", recipes:typeof BAKES_RECIPES!=='undefined'?BAKES_RECIPES:[],          sub:"Cakes · Biscuits · Breads · Desserts", cats:[{id:'breads',e:'🍞',l:'Breads & Rolls'},{id:'flatbreads',e:'🫓',l:'Flatbreads'},{id:'sconesmuffins',e:'🧁',l:'Scones & Muffins'},{id:'biscuits',e:'🍪',l:'Biscuits & Rusks'},{id:'cakes',e:'🎂',l:'Cakes & Cupcakes'},{id:'cheesecakes',e:'🍰',l:'Cheesecakes'},{id:'pastries',e:'🥐',l:'Pastries & Tarts'},{id:'puddings',e:'🍮',l:'Puddings & Desserts'},{id:'deepfried',e:'🍩',l:'Deep-Fried'}]},
    sidesbasics:{title:"Sides & Basics",    emoji:"🍟", color:"#c08040", bg:"#180f08", border:"#3a2410", recipes:typeof SIDES_BASICS_RECIPES!=='undefined'?SIDES_BASICS_RECIPES:[], sub:"Chips · Mash · the building blocks", cats:[{id:'potato',e:'🥔',l:'Potato Sides'},{id:'rice',e:'🍚',l:'Rice & Grains'},{id:'staples',e:'🍝',l:'Staples & Doughs'},{id:'sauces',e:'🥫',l:'Basic Sauces'}]},
  };
  const cfg = configs[sectionKey];
  if(!cfg) return comingSoonHTML("🍽️","Section","Coming soon");

  // Plan view
  if(S.mealPlanView){
    window._sectionPlanForShare = S.mealPlan||[];
    return sectionPlanView('mealPlan', cfg.title+' Plan', cfg.emoji||'🍽️', cfg.color, cfg.bg, cfg.border, S.searchServings||4, "setQuiet({mealPlanView:false})");
  }

  // Recipe detail view
  const activeRecipe = S.mealActiveRecipe;
  if(activeRecipe && activeRecipe._section===sectionKey){
    return recipeDetailFromResult(activeRecipe, "closeMealRecipe()", S.searchServings||4, cfg.color, cfg.bg, cfg.border);
  }

  // List view
  const sort = S.mealSort||'popular';
  let recipes = [...(cfg.recipes||[])];
  // P4: surface canonical cards from other sections on the Lunch shelf (e.g. Shakshuka).
  if(sectionKey==='lightlunch' && typeof lunchInject==='function') recipes = lunchInject(recipes);

  // Category pills (braai-style) — only for sections that define cfg.cats
  const cats = cfg.cats || null;
  let activeCat = null, activeCatObj = null;
  if(cats){
    activeCat = cats.find(c=>c.id===S.mealCat) ? S.mealCat : cats[0].id;
    activeCatObj = cats.find(c=>c.id===activeCat);
    recipes = recipes.filter(r=>r.cat===activeCat);
  }

  // Search · MF46 — the shelf list no longer filters here; liveSearch writes #mealSearchResults
  // directly (never draw()), so the input survives the keystroke. Scoped to section 'meals'.

  if(sort==='az') recipes.sort((a,b)=>a.name.localeCompare(b.name));
  else if(sort==='time') recipes.sort((a,b)=>(a.time||0)-(b.time||0));
  else {
    // 'popular' (default) — honour an optional curated `order` field so section order is
    // set by DATA, not array position. Lower `order` = earlier; cards without it keep
    // their existing relative order (stable via index tiebreak). No card carries `order`
    // yet, so this is a no-op until one is added — zero regression. (P6 — featured/order.)
    recipes = recipes
      .map((r,i)=>({r:r,i:i}))
      .sort((a,b)=>{
        const ao=(a.r.order!=null)?a.r.order:Infinity, bo=(b.r.order!=null)?b.r.order:Infinity;
        return (ao-bo) || (a.i-b.i);
      })
      .map(x=>x.r);
  }

  const mealHowOpen = S.mealHowOpen || false;
  // MF56 · per-sub-screen search scope — Breakfast searches Breakfast (mealCat), NOT all Family Meals.
  const _scp = ({ breakfast:{s:['meals'],mc:'breakfast',lbl:'Breakfast'}, lightlunch:{s:['meals'],mc:'lunch',lbl:'Light Lunch'}, supper:{s:['meals'],mc:'supper',lbl:'Supper'}, bakes:{s:['bakes'],mc:null,lbl:'Bakes & Cakes'}, sidesbasics:{s:['meals'],mc:null,lbl:'Sides & Basics'} })[sectionKey] || {s:['meals'],mc:null,lbl:cfg.title};
  // single-quote the array — this string lives inside a double-quoted oninput="…" HTML attribute
  const _mealSearchOninput = "liveSearch(this,'mealSearchResults',{sections:['"+_scp.s.join("','")+"'],mealCat:"+(_scp.mc?("'"+_scp.mc+"'"):'null')+",label:'"+_scp.lbl+"',stateKey:'mealSearch'})";

  return `<div>
    ${sectionHeader({
      title: cfg.title, emoji: cfg.emoji, tagline: cfg.sub,
      img: 'https://raw.githubusercontent.com/tinavdw/tinza/main/Images/Headers/'+encodeURIComponent(cfg.title)+'.jpg',
      backJs: "set({screen:'feedfamily',mealSearch:''})", backLabel: '← Family Meals',   // MF59 · don't carry the query out of the sub-screen
      myPlan: { count:(S.mealPlan||[]).length, onclick:"setQuiet({mealPlanView:true})" },
      search: { value:searchVal('mealSearch'), oninput:_mealSearchOninput, clearJs:"set({mealSearch:'',searchResults:[]})", placeholder:'Search '+cfg.title.toLowerCase()+' recipes…' },
      cats: cats ? cats.map(c=>({ emoji:c.e, label:c.l, active:(activeCat===c.id), onclick:"setQuiet({mealCat:'"+c.id+"'});setTimeout(()=>{var el=document.getElementById('mealGroupTop');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});},60)" })) : []
    })}
    <div class="content" style="padding:12px 16px;max-width:600px;margin:0 auto;">
      <div id="mealSearchResults"></div>
      ${howItWorks({ steps:[
        '1 · Browse each shelf and tap a card to read the full recipe first',
        '2 · Tick the <strong style="color:var(--gold);">☑ checkbox</strong> on any dish to add it to your plan',
        '3 · Add more dishes — portions <strong style="color:var(--gold);">scale automatically</strong>',
        '4 · Tap <strong style="color:var(--gold);">My Plan</strong> for quantities, cost &amp; shopping list',
        '5 · Share your list straight to WhatsApp or your store'
      ] })}
      <!-- Sort pills (token-driven) -->
      <div style="display:flex;gap:6px;justify-content:flex-end;margin-bottom:10px;">
        ${[{id:'popular',l:'⭐ Popular'},{id:'az',l:'A–Z'},{id:'time',l:'⏱️ Quick'}].map(s=>`<button onclick="setQuiet({mealSort:'${s.id}'})" style="padding:6px 12px;border-radius:20px;border:1px solid ${sort===s.id?'var(--accent)':'var(--line)'};background:${sort===s.id?'var(--card2)':'var(--card)'};color:var(--ink);font-weight:${sort===s.id?'bold':'normal'};font-size:13px;cursor:pointer;">${s.l}</button>`).join('')}
      </div>
      ${cats?`<div id="mealGroupTop" style="font-size:15px;letter-spacing:1px;color:var(--ink);font-weight:bold;text-transform:uppercase;padding:6px 0 8px;border-bottom:1px solid var(--line);margin-bottom:10px;">${activeCatObj.e} ${activeCatObj.l} · ${recipes.length} ${recipes.length===1?'kind':'kinds'}</div>`:`<div style="font-size:13px;color:var(--ink-soft);margin-bottom:10px;">${recipes.length} recipes</div>`}
      ${recipes.length===0?`<div style="padding:22px;text-align:center;color:var(--ink-soft);font-size:13px;background:var(--card);border:1px solid var(--line);border-radius:10px;margin-bottom:6px;">Nothing here yet — try another category${searchVal('mealSearch')?' or clear your search':''}.</div>`:''}
      ${recipes.map((r,i)=>{
        const inPlan = isPlanItem('mealPlan', r.id);
        // Shared Warm Spice photo card (Rule Zero) — identical to World Kitchen's
        // wkRecipeCard. Top-left checkbox toggles the EXISTING meal plan
        // (toggleMealPlan, NOT wkPlanToggle); the card opens via openMealRecipe.
        // Cost chip shows ONLY when the meal carries a per-person cost (else blank).
        const metaTxt = [r.feel, (r.time?'⏱️ '+((typeof fmtCookTime==='function')?fmtCookTime(r.time):r.time+' min')+((typeof isMakeAhead==='function'&&isMakeAhead(r.time))?' · make-ahead':''):'')].filter(Boolean).join(' · ');
        return warmCard({
          name: dietTag(r.diet)+r.name,
          photoName: r.name,
          emoji: r.emoji || '🍽️',
          sub: r.cuisine || '',
          meta: metaTxt,
          costPP: r.costPP || '',
          versions: (r.versions && r.versions.length) || 0,
          openJs: "openMealRecipe('"+r.id+"')",
          toggleJs: "toggleMealPlan('"+r.id+"')",
          sel: inPlan
        });
      }).join('')}
      ${sectionPlanBtn('mealPlan', cfg.title, cfg.emoji||'🍽️', cfg.color, cfg.bg, S.searchServings||4, "setQuiet({mealPlanView:true})")}
    </div>
  </div>`;
}

