// ── 4 INGREDIENTS & ANCHOR INGREDIENT ────────────────────────────

async function findFourIngredients(){
  if (S._fourAILoading) return;   // MF108 · the chef is already thinking. Do not bill her twice.
  const ing = [
    S.ing1||'', S.ing2||'', S.ing3||'', S.ing4||''
  ].map(i=>i.trim()).filter(Boolean);

  if(ing.length < 2){
    setQuiet({_fourError:'Please enter at least 2 ingredients', _fourResults:null, _fourLoading:false});
    return;
  }

  setQuiet({_fourLoading:true, _fourResults:null, _fourError:null});

  // MF77 — the finder reads the ONE index. No second corpus. ⚖️ Law 6.
  // mealRole is the finder switch (index.js:83). It already excludes
  // pet / baby / condiment / drink / bake / basic — the dog food excludes itself.
  const pool = (typeof allRecipes === 'function')
    ? (allRecipes({ mealRole: ['main','side'] }) || [])
    : [];

  // MF85 — 13 recipes keep their food inside versions[] and leave the top-level
  // ingredients array EMPTY. Read both, or Creamy Mac & Cheese can never be found.
  const ingredientText = (r) => {
    const names = (list) => (Array.isArray(list) ? list : [])
      .map(x => typeof x === 'string' ? x : (x && (x.n || x.name) || ''))
      .join(' ');
    return (names(r.ingredients) + ' ' +
            (r.versions || []).map(v => names(v.ingredients)).join(' ')).toLowerCase();
  };

  // ⚖️ LAW 41 — A MATCH OF 2-OF-4 IS NOT A MATCH. IT IS A COINCIDENCE.
  // Measured 13 Jul: at 2-of-4, mince+potato+onion+tomato returns a GREEK SALAD (214 hits).
  // At 3-of-4 it returns Cottage Pie, Shepherd's Pie, Moussaka. The threshold IS the feature.
  // 2 in → 2 of 2 · 3 in → 3 of 3 · 4 in → 3 of 4.
  const need = Math.min(ing.length, 3);

  const ingLower = ing.map(i => i.toLowerCase());
  const dbMatches = [];
  pool.forEach(r => {
    const hay = ingredientText(r);            // ingredients ONLY — never the trivia or chefNotes
    const matched = ingLower.filter(i => hay.includes(i));
    if (matched.length >= need) {
      dbMatches.push({ ...r, _matchCount: matched.length, _matched: matched, _source: 'db' });
    }
  });
  dbMatches.sort((a, b) => b._matchCount - a._matchCount);

  // ── MF77-B — the app answers first, the chef catches up ─────────────
  // Copied from callMoodChef() (core.js:1959). Show the DB now. Draw. Then fire.
  const cacheKey = ingLower.slice().sort().join('|');

  setQuiet({
    _fourResults : dbMatches,          // ALL of them — never a slice ⚖️ Law 36
    _fourPage    : 5,                  // show 5, "show more" adds 5
    _fourLoading : false,              // ← THE SPINNER IS OFF. She is already reading.
    _fourError   : dbMatches.length ? null : null,
    _fourAI      : null,
    _fourAILoading : false
  });
  draw();

  // Tinza Chef only wakes up when the app is THIN — and only for Pro. (Tina, 13 Jul.)
  if (dbMatches.length < 10 && typeof tierLevel === 'function' && tierLevel() >= 1) {
    startFourAIFetch(ing, dbMatches, cacheKey);   // fire and FORGET. No await.
  }
}

// ── MF77-B — Tinza Chef, in the background. Never blocks. ───────────────
const _fourCache = {};   // same fridge → never a second API call (⚖️ Law 20)

async function startFourAIFetch(ing, dbMatches, cacheKey){
  if (S._fourAILoading || S._fourAI) return;                 // already running / done
  if (_fourCache[cacheKey]) {                                // free, instant
    setQuiet({ _fourAI: _fourCache[cacheKey] }); draw(); return;
  }
  setQuiet({ _fourAILoading: true }); draw();

  // The names the app already gave her. The chef may NEVER repeat one.
  const taken = dbMatches.map(r => r.name).join(', ');

  const prompt = `You are Tinza Chef, a South African recipe assistant.
The cook has: ${ing.join(', ')}.

Suggest 4 REAL, EXISTING dishes that genuinely use these ingredients.

ABSOLUTE RULES — breaking any one of these is a failure:
1. NEVER alter a traditional dish to fit the ingredients. A bobotie has no potato in it.
   If a classic dish does not truly use these ingredients, DO NOT suggest it.
2. NEVER use the name of a traditional or named dish (Bobotie, Cottage Pie, Bunny Chow,
   Moussaka, Bredie, Potjiekos...). Give an honest descriptive name instead:
   "Mince & Potato Bake", not "Bobotie".
3. NEVER suggest any of these — the app has already offered them: ${taken || '(none)'}
4. If an ingredient the cook has does not belong in the dish, LEAVE IT OUT and say so
   in "missing" — do not force it in.
5. South African ingredients and shops. Grams and millilitres only.

Return ONLY a JSON array of exactly 4 (no markdown, no backticks):
[{"name":"Honest Descriptive Name","emoji":"single emoji","time":30,"cuisine":"style",
  "uses":["ingredient"],"missing":["what she still needs"],"serves":4,
  "ingredients":[{"n":"name","pp":100,"u":"g","userHas":true}],
  "method":["Step 1","Step 2"],"tip":"One useful tip"}]`;

  try {
    const resp = await fetch('/.netlify/functions/claude', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ model:'claude-sonnet-4-20250514', max_tokens:2000,
        messages:[{ role:'user', content: prompt }] })
    });
    const data  = await resp.json();
    const text  = (data.content||[]).map(b=>b.text||'').join('');
    const clean = text.replace(/```json|```/g,'').trim();
    let chef = JSON.parse(clean);
    if (!Array.isArray(chef)) chef = [];

    // BELT AND BRACES — the model was told not to repeat. Enforce it anyway. ⚖️ Law 22.
    const takenLower = dbMatches.map(r => String(r.name).toLowerCase().trim());
    chef = chef.filter(r => r && r.name && !takenLower.includes(String(r.name).toLowerCase().trim()));
    chef.forEach(r => { r._source = 'chef'; r._matchCount = (r.uses||[]).length; });

    _fourCache[cacheKey] = chef;
    setQuiet({ _fourAI: chef, _fourAILoading: false });
    draw();                                      // she never sees it arrive
  } catch (e) {
    setQuiet({ _fourAILoading: false });         // the app results stay. Nothing is lost.
    draw();
  }
}

async function findAnchorIngredient(){
  const raw = (S.anchorInput||'').trim();
  if(!raw){
    setQuiet({_anchorError:'Please enter an ingredient', _anchorResults:null, _anchorLoading:false});
    return;
  }

  setQuiet({_anchorLoading:true, _anchorResults:null, _anchorError:null});

  // Parse quantity if given e.g. "beef mince 300g" or "whole chicken 1.1kg"
  const qtyMatch = raw.match(/([\d.]+)\s*(g|kg|ml|L|l)(?![a-z])/i);
  const ingredient = raw.replace(/([\d.]+)\s*(g|kg|ml|L|l)(?![a-z])/gi,'').replace(/^\s*[\d.]+\s+/,'').trim();
  const userQty = qtyMatch ? parseFloat(qtyMatch[1]) * (qtyMatch[2].toLowerCase()==='kg'?1000:qtyMatch[2].toLowerCase()==='l'?1000:1) : null;
  const userUnit = qtyMatch ? (qtyMatch[2].toLowerCase()==='kg'?'g':qtyMatch[2].toLowerCase()==='l'?'ml':qtyMatch[2].toLowerCase()) : null;

  // Search database
  const allRecipes = [
    ...(BREAKFAST_RECIPES||[]), ...(LIGHTLUNCH_RECIPES||[]),
    ...(SUPPER_RECIPES||[]), ...(BAKES_RECIPES||[]),
    ...(POPULAR_RECIPES.sa||[]), ...(POPULAR_RECIPES.international||[]),
  ];
  const ingLower = ingredient.toLowerCase();
  const dbMatches = allRecipes.filter(r=>JSON.stringify(r).toLowerCase().includes(ingLower))
    .map(r=>({...r, _source:'db', _userQty:userQty, _userUnit:userUnit, _ingredient:ingredient}));

  // Call Tinza Chef
  try {
    const qtyNote = userQty ? ` The user has exactly ${userQty}${userUnit} of ${ingredient}.` : '';
    const prompt = `You are Tinza Chef, a South African recipe assistant.
The user has: ${raw}.${qtyNote}

Generate 4 different recipes that use ${ingredient} as the main ingredient.
${userQty ? `Scale each recipe to use approximately ${userQty}${userUnit} of ${ingredient}.` : ''}

Return ONLY a JSON array (no markdown, no backticks):
[
  {
    "name": "Recipe Name",
    "emoji": "single emoji",
    "time": 30,
    "cuisine": "cuisine type",
    "serves": 4,
    "mainIngredientPP": 150,
    "mainIngredientUnit": "g",
    "ingredients": [
      {"n": "${ingredient}", "pp": 150, "u": "g", "userHas": true},
      {"n": "other ingredient", "pp": 20, "u": "g", "userHas": false}
    ],
    "method": ["Step 1", "Step 2", "Step 3"],
    "tip": "One useful tip"
  }
]

Rules: all amounts in g or ml, pp = per serving, userHas true only for ${ingredient}`;

    const resp = await fetch('/.netlify/functions/claude', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body:JSON.stringify({model:'claude-sonnet-4-20250514', max_tokens:2000,
        messages:[{role:'user',content:prompt}]})
    });
    const data = await resp.json();
    const text = (data.content||[]).map(b=>b.text||'').join('');
    const clean = text.replace(/```json|```/g,'').trim();
    const chefRecipes = JSON.parse(clean);
    chefRecipes.forEach(r=>{ r._source='chef'; r._userQty=userQty; r._userUnit=userUnit; r._ingredient=ingredient; });

    setQuiet({_anchorResults:[...dbMatches.slice(0,2),...chefRecipes], _anchorLoading:false, _anchorError:null});
  } catch(e){
    setQuiet({_anchorResults:dbMatches, _anchorLoading:false,
      _anchorError:dbMatches.length===0?'No recipes found. Try a different ingredient.':null});
  }
}

