// ── veg/vegan badge: green "V" (vegetarian) or "VG" (vegan); blank for meat or
//    any recipe without a diet tag (so other sections are unaffected). ──
function dietTag(d){
  if(d!=='veg' && d!=='vegan') return '';
  var bg    = d==='vegan' ? '#1f7a3d' : '#c8e840';   // vegan = deep green · vegetarian = lime
  var fg    = d==='vegan' ? '#eafbe0' : '#2c3a06';
  var label = d==='vegan' ? 'VG' : 'V';
  var title = d==='vegan' ? 'Vegan' : 'Vegetarian';
  return '<span title="'+title+'" style="display:inline-block;font-size:10px;font-weight:800;line-height:1;color:'+fg+';background:'+bg+';border-radius:5px;padding:2px 5px;margin-right:6px;vertical-align:middle;letter-spacing:0.02em;">'+label+'</span>';
}

function recipeResultCard(r, onClickFn, color){
  const matchBadge = r._matchCount ? `<span style="background:#1f1206;border:1px solid #c06020;border-radius:8px;font-size:13px;color:#f5c842;padding:2px 6px;margin-right:3px;">✓ ${r._matchCount} ingredient${r._matchCount>1?'s':''} matched</span>` : '';
  const sourceBadge = r._source==='db' ? `<span style="background:#161210;border:1px solid #4a3018;border-radius:8px;font-size:13px;color:#e0d4b8;padding:2px 6px;">In Tinza</span>` : '';
  return `<div onclick="${onClickFn}" style="background:#141210;border:1px solid #2a2820;border-radius:10px;padding:12px;margin-bottom:8px;cursor:pointer;display:flex;align-items:center;gap:12px;">
    <span style="font-size:28px;flex-shrink:0;">${r.emoji||'🍽️'}</span>
    <div style="flex:1;min-width:0;">
      <div style="font-size:14px;color:#f5e8cc;margin-bottom:3px;">${r.name}</div>
      <div style="font-size:13px;color:${color||'#e0d4b8'};">${r.cuisine||''} · ⏱️ ${r.time?r.time+' min':'—'}</div>
      <div style="margin-top:4px;">${matchBadge}${sourceBadge}</div>
    </div>
    <span style="color:${color||'#c06020'};font-size:14px;flex-shrink:0;">→</span>
  </div>`;
}

// ── PART I — BAKES PORTION MODEL (BATCH LAW · approved 6 Jul 2026) ────────────
// Bakes are YIELD-based: you can't bake a third of a cake. The guest dial stays on
// PEOPLE everywhere (one shared control = sameness), but bakes ANSWER in whole units
// — people round UP to whole cakes/batches, cost is per whole unit, per-person = total÷people.
// Defaults apply only to UNAMBIGUOUS cats; a card overrides via `serves` (sliceable)
// or `makes` (batch). Countable singles (breads/flatbreads/quickbreads = 1 item pp)
// and mixed pastries stay per-person unless the card carries its own serves/makes,
// so nothing is mis-yielded. APPROVED DEFAULTS: cake/cheesecake serves 12 · biscuits makes ~30.
// (tart 8–10 · loaf 10 land per-card via `serves` — they live in mixed cats.)
var BAKES_SLICE_DEFAULT = { cakes:12, cheesecakes:12 };
var BAKES_BATCH_DEFAULT = { biscuits:30 };
function bakesPortion(r){
  if(!r) return null;
  // MF110 — bakesPortion() only ever speaks for BAKES. A mood card (core.js:1938 bolts on
  // serves:1), a mood AI card (core.js:1963 _fromAI) and a chef card (meals.js:15667/15742
  // _source:'chef', prompt writes "serves":4) all carry `serves` but are NOT bakes — so a
  // rice bowl / chicken dish rendered "makes N cakes · serves N · 1 slice each".
  if (r._fromDB || r._fromAI || r._source === 'chef') return null;
  var cat = (r.cat||'').toLowerCase();
  if(r.serves) return { mode:'slice', perBatch:r.serves, unitWord:(cat==='cheesecakes'?'cheesecake':cat==='pastries'?'tart':'cake'), pieceWord:'slice' };
  if(r.makes)  return { mode:'batch', perBatch:r.makes,  unitWord:'batch', pieceWord:'piece' };
  if(BAKES_SLICE_DEFAULT[cat]) return { mode:'slice', perBatch:BAKES_SLICE_DEFAULT[cat], unitWord:(cat==='cheesecakes'?'cheesecake':'cake'), pieceWord:'slice' };
  if(BAKES_BATCH_DEFAULT[cat]) return { mode:'batch', perBatch:BAKES_BATCH_DEFAULT[cat], unitWord:'batch', pieceWord:'piece' };
  return null;
}

function recipeDetailFromResult(r, backAction, servings, color, bg, border){
  if(typeof applyRecipeVersion==='function') r = applyRecipeVersion(r);   // ⭐ versions: render the chosen version
  // MF144 · seed through the shared softDefaultN (one door with bakes + WK + health).
  // A soft oven-dish opens at serves 6; any real user count wins (it's first). Non-soft →
  // softDefaultN returns the original per-path default (4/1/4) → byte-identical.
  const sv = S._budgetActiveRecipe ? (S.budgetPeople||softDefaultN(r,4))
           : S.moodActiveRecipe    ? (S.moodServings||softDefaultN(r,1))
           : (S.searchServings||softDefaultN(r,4));

  // PART I — bakes answer in WHOLE units. _scale = the ingredient/cost multiplier:
  // whole slices/pieces produced for a modelled bake, else the raw people count.
  var _bakeP = (typeof bakesPortion==='function') ? bakesPortion(r) : null;
  var _bakeBatches = _bakeP ? Math.max(1, Math.ceil(sv / _bakeP.perBatch)) : 1;
  var _bakeUnits = _bakeP ? _bakeBatches * _bakeP.perBatch : 0;
  var _scale = _bakeP ? _bakeUnits : sv;
  var _incW=_bakeP?_bakeP.perBatch*(_bakeBatches+1):0, _decW=_bakeP?Math.max(1,_bakeP.perBatch*(_bakeBatches-1)):0;
  var _bakeUnitLbl=_bakeP?(_bakeBatches+' '+_bakeP.unitWord+(_bakeBatches>1?'s':'')):'';
  // MF144 · the SOFT oven-dish assumption line — shared softDishNote, suppressed for a
  // modelled bake. '' otherwise → byte-identical. One door with bakes + WK + health.
  var _softNote = _bakeP ? '' : softDishNote(r);

  function fmtAmt(pp, u){
    if(!pp) return '';
    const raw = pp * _scale;
    if(u==='egg') return Math.ceil(raw)+' egg'+(Math.ceil(raw)>1?'s':'');
    if((u==='g'||u==='ml')&&raw>=1000) return (Math.round(raw/100)/10)+(u==='g'?'kg':'L');
    return Math.round(raw*10)/10+(u||'');
  }

  // _rid / _saved / S.savedRecipes deleted 15 Jul — the heart (top-right of the photo
  // header) is the only save, and it reads tinzaStore, not S. ⚖️ Law 6 — one door.
  const _isPro = tierAllows('pro');

  // THE HEART — the SAME shared control recipePage renders. ⚖️ Law 6: CALL it, never
  // rebuild it; its onclick fires toggleRecipeFavourite() through the one door.
  // This view has FIVE callers and none of them had a save: FMF (mealActiveRecipe),
  // the budget finder, search results, 4-Ingredients and Anchor.
  //   · FMF stamps _section with the SCREEN name (supper/bakes/sidesbasics …) —
  //     VR_TYPE_SECTION maps it to the index section.
  //   · The other four pass an allRecipes() record, whose .section IS the index section.
  // Either way recipeFavRecord() resolves the canonical record, so a dish favourited
  // here and the same dish favourited in Braai write the SAME key. Measured 15 Jul.
  const _favVr = { type: (r._section || r.section || ''), id: r.id };
  const _heart = (typeof favouriteHeart === 'function') ? favouriteHeart(_favVr) : '';
  const _rname = (r.name||'').replace(/'/g,'').replace(/"/g,'');
  const _remoji = r.emoji||'🍽️';

  // WhatsApp text built outside template literal
  const _waLines = (r.ingredients||[]).filter(i=>i.pp).map(i=>{
    const raw=i.pp*_scale, u=i.u||'';
    const d=(raw>=1000&&(u==='g'||u==='ml'))?(Math.round(raw/100)/10)+(u==='g'?'kg':'L'):(Math.round(raw*10)/10)+u;
    return '• '+i.n+': '+d;
  }).join('\n');
  const _waText = encodeURIComponent(
    _remoji+' *'+_rname+'*\nFor '+sv+' people · '+(r.time?((typeof fmtCookTime==='function')?fmtCookTime(r.time):r.time+' min'):'?')+'\n\nIngredients:\n'+_waLines+'\n\nFrom Tinza tinza.netlify.app'
  );

  // Cost estimate (if ingredients have costPP or we can estimate)
  const _costEstimate = (()=>{
    if(!_isPro) return `<div style="background:#1a1008;border:1px dashed #5a3010;border-radius:10px;padding:14px;margin-bottom:12px;text-align:center;">
      <div style="font-size:22px;color:#bf6d24;letter-spacing:6px;margin-bottom:6px;">R • • • •</div>
      <div style="font-size:13px;color:#c86449;">💰 Cost estimate — <strong style="color:${color};">Tinza Pro R50/month</strong></div>
    </div>`;
    if(r.costPP){
      const total = r.costPP * _scale;
      return `<div style="background:#0f1a08;border:1px solid #5a8010;border-radius:10px;padding:14px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:#8ab030;text-transform:uppercase;margin-bottom:10px;">💰 Food Cost</div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
          <div style="font-size:13px;color:#718933;">Total for ${sv} people</div>
          <div style="font-size:24px;font-weight:bold;color:#c8e840;">R${total}</div>
        </div>
        <div style="display:flex;justify-content:space-between;padding-top:8px;border-top:1px solid #2a3010;">
          <div style="font-size:13px;color:#6a892e;">Per person</div>
          <div style="font-size:16px;font-weight:bold;color:#a0c030;">R${_bakeP?Math.round((r.costPP*_scale)/sv):r.costPP}</div>
        </div>
        <div style="margin-top:8px;font-size:13px;color:#748932;">SA&#39;s biggest retailers · ${PRICE_ASOF} · Always buy 10% extra.</div>
      </div>`;
    }
    return '';
  })();

  // ── WARM BRANCH (Session 2 · inWarm() guard) ─────────────────────────────────
  // FMF (once added to _warm/inWarm) renders the parchment recipe page here, matching
  // braai / World Kitchen — token-driven, one accent (no per-section purple/maroon),
  // cream qty card like the shared qtyBox(). Every NON-warm caller (budget · mood ·
  // search · 4-ingredients · anchor) skips this whole block and falls through to the
  // ORIGINAL return below, byte-for-byte unchanged — this is a PURE INSERTION, so the
  // 5 non-FMF callers cannot regress and Mood keeps its colour exception on that path.
  if((typeof inWarm==='function') && inWarm()){
    const ingRowsW = (r.ingredients||[]).map(i=>{
      if(!i.pp) return `<div style="padding:5px 0;border-bottom:1px solid var(--line);font-size:13px;color:var(--ink-soft);font-style:italic;">• ${i.n} — to taste</div>`;
      const raw=i.pp*_scale, u=i.u||'';
      const ppStr=i.pp+(u==='egg'?' egg':u)+' pp';
      const totalStr=u==='egg'?Math.ceil(raw)+' egg'+(Math.ceil(raw)>1?'s':'')
        :(raw>=1000&&(u==='g'||u==='ml'))?(Math.round(raw/100)/10)+(u==='g'?'kg':'L')
        :Math.round(raw*10)/10+u;
      const _lk=(typeof crossLinkFor==='function'&&typeof INGREDIENT_LINKS!=='undefined')?crossLinkFor(INGREDIENT_LINKS,i.n):null;
      return `<div style="display:flex;gap:8px;padding:7px 0;border-bottom:1px solid var(--line);">
        <span style="color:var(--accent);flex-shrink:0;">•</span>
        <span style="font-size:14px;color:var(--ink2);flex:1;">${_lk?`<span onclick="${_lk}" style="color:var(--accent);font-weight:bold;cursor:pointer;text-decoration:underline;text-decoration-style:dotted;">${i.n} ↗</span>`:i.n} — <span style="color:var(--ink-soft);font-size:13px;">${ppStr}</span> · <strong style="color:var(--gold);">${totalStr} total</strong></span>
      </div>`;
    }).join('');
    const rawShrinkW = (r.ingredients||[]).some(i=>/rice|pap|mealie|samp|meat|mince|chicken|beef|lamb|pork|steak|wors|sausage|fish|snoek|bacon|biltong|chop|\brib/i.test(i.n));
    const methodRowsW = (r.method||[]).map((step,si)=>{
      const _sec=(typeof parseStepTime==='function')?parseStepTime(step):0;
      const _tmr=!_sec?'':(tierAllows('pro')?`<div style="margin-top:7px;"><button onclick="startTimer(${_sec},'Step ${si+1}')" style="display:inline-block;background:var(--card2);border:1px solid var(--accent);border-radius:6px;color:var(--gold);font-size:13px;font-weight:bold;padding:4px 11px;cursor:pointer;">⏱️ ${(typeof fmtTimerLabel==='function')?fmtTimerLabel(_sec):Math.round(_sec/60)+' min'}</button></div>`:`<div style="margin-top:7px;"><span style="display:inline-block;background:var(--card2);border:1px dashed var(--line);border-radius:6px;color:var(--ink-soft);font-size:13px;padding:4px 11px;">⏱️ ${(typeof fmtTimerLabel==='function')?fmtTimerLabel(_sec):Math.round(_sec/60)+' min'} · 🔒 Pro</span></div>`);
      return `<div style="display:flex;gap:12px;margin-bottom:14px;"><div style="width:24px;height:24px;border-radius:50%;background:var(--accent);border:1px solid var(--accent);color:var(--on-media);font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${si+1}</div><div style="flex:1;"><p style="margin:2px 0 0;font-size:14px;color:var(--ink2);line-height:1.7;">${step}</p>${_tmr}</div></div>`;
    }).join('');
    const scaleNoteW = _bakeP?(_bakeP.mode==='slice'?('makes '+_bakeBatches+' '+_bakeP.unitWord+(_bakeBatches>1?'s':'')+' · serves '+_bakeUnits+' · 1 '+_bakeP.pieceWord+' each'):('makes '+_bakeBatches+' '+_bakeP.unitWord+(_bakeBatches>1?'s':'')+' · ~'+_bakeUnits+' '+_bakeP.pieceWord+'s')):'people · all quantities scale';
    const noteW = _bakeP?('💡 Bakes come in whole '+_bakeP.unitWord+'s — the dial rounds up so you never bake a fraction.'):'💡 Adjust the number and all ingredients update instantly.';
    const costW = (()=>{
      if(!_isPro) return `<div style="background:var(--card2);border:1px dashed var(--accent);border-radius:10px;padding:14px;margin-bottom:12px;text-align:center;">
        <div style="font-size:22px;color:var(--accent);letter-spacing:6px;margin-bottom:6px;">R • • • •</div>
        <div style="font-size:13px;color:var(--ink-soft);">💰 Cost estimate — <strong style="color:var(--accent);">Tinza Pro R50/month</strong></div></div>`;
      if(r.costPP){ const total=r.costPP*_scale; return `<div style="background:var(--green-tint);border:1px solid var(--green-soft);border-radius:10px;padding:14px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:var(--green);text-transform:uppercase;margin-bottom:10px;">💰 Food Cost</div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-size:13px;color:var(--ink-soft);">${_bakeP?("Total · "+_bakeUnitLbl):("Total for "+sv+" people")}</div><div style="font-size:24px;font-weight:bold;color:var(--green);">R${total}</div></div>
        <div style="display:flex;justify-content:space-between;padding-top:8px;border-top:1px solid var(--line);"><div style="font-size:13px;color:var(--ink-soft);">${_bakeP?("Per "+_bakeP.pieceWord):"Per person"}</div><div style="font-size:16px;font-weight:bold;color:var(--green);">R${_bakeP?Math.round((r.costPP*_scale)/_bakeUnits):r.costPP}</div></div>
        <div style="margin-top:8px;font-size:13px;color:var(--ink-soft);">SA&#39;s biggest retailers · ${PRICE_ASOF} · Always buy 10% extra.</div></div>`; }
      return '';
    })();
    return `<div style="min-height:100vh;background:var(--bg);">
      <div style="position:relative;">
        ${(typeof recipePhoto==='function')?recipePhoto(r.photoName||r.name, r.emoji, 200):''}
        <button onclick="${backAction}" style="position:absolute;top:10px;left:10px;z-index:3;background:rgba(8,4,2,0.55);border:1px solid rgba(255,255,255,0.55);border-radius:20px;color:#fff;font-size:13px;padding:5px 12px;cursor:pointer;">← Back</button>
        ${_heart}
      </div>
      <div class="content" style="padding:0 16px 16px;max-width:600px;margin:0 auto;">
        <h1 class="ttl" style="font-size:26px;font-weight:600;color:var(--ink);margin:10px 0 2px;line-height:1.15;">${r.emoji||'🍽️'} ${dietTag(r.diet)}${(typeof tinzaDisplayName==='function')?tinzaDisplayName(r):r.name}</h1>
        ${r.feel?`<div style="font-style:italic;color:var(--ink-soft);font-size:14px;line-height:1.5;margin:4px 0 14px;">“${r.feel}”</div>`:'<div style="height:8px;"></div>'}
        ${typeof versionStripHTML==='function'?versionStripHTML(r,'var(--accent)'):''}
        <!-- How much to make — warm cream card, matches shared qtyBox() -->
        <div style="background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:14px;margin-bottom:14px;box-shadow:0 10px 24px -18px rgba(120,70,30,0.45);">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;">
            <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;">How Much To Make</div>
            <div style="display:flex;align-items:center;gap:10px;flex-shrink:0;">
              <button onclick="const _k=S._budgetActiveRecipe?'budgetPeople':S.moodActiveRecipe?'moodServings':'searchServings';setQuiet({[_k]:${_bakeP?_decW:'Math.max(1,(S[_k]||4)-1)'}})" aria-label="fewer servings" style="width:36px;height:36px;border-radius:50%;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:20px;line-height:1;cursor:pointer;">−</button>
              <span class="mono" style="font-size:20px;color:var(--ink);font-weight:600;min-width:26px;text-align:center;">${_bakeP?_bakeBatches:sv}</span>
              <button onclick="const _k=S._budgetActiveRecipe?'budgetPeople':S.moodActiveRecipe?'moodServings':'searchServings';setQuiet({[_k]:${_bakeP?_incW:'Math.min(500,(S[_k]||4)+1)'}})" aria-label="more servings" style="width:36px;height:36px;border-radius:50%;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:20px;line-height:1;cursor:pointer;">+</button>
            </div>
          </div>
          <div style="font-size:13px;color:var(--ink-soft);margin-top:8px;">${_bakeP?scaleNoteW:(sv+" "+(sv===1?"person":"people")+" · "+scaleNoteW)}</div>
          ${_softNote?`<div style="margin-top:6px;font-size:12.5px;color:var(--ink-soft);">${_softNote}</div>`:''}
          <div style="margin-top:8px;font-size:12.5px;color:var(--ink-soft);">${noteW}</div>
        </div>
        ${equipmentContract(r, _bakeP?_bakeUnits:sv, _bakeP?_bakeP.unitWord:null, _bakeBatches)}${equipmentLine(r, _bakeP?_bakeUnits:sv)}
        <!-- Ingredients -->
        <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px;margin-bottom:12px;">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
            <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;">Ingredients</div>
            <div style="font-size:13px;color:var(--ink-soft);font-style:italic;">${_bakeP?("for "+_bakeUnitLbl):("scaled for "+sv+" "+(sv===1?"person":"people"))}</div>
          </div>
          ${ingRowsW}
          ${rawShrinkW?`<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--line);font-size:13px;color:var(--ink-soft);font-style:italic;">📏 Raw/dry weights · Rice+pap grow 3x when cooked · Meat shrinks ~25%</div>`:''}
        </div>
        <!-- Method -->
        <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px;margin-bottom:12px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:10px;">
            <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;">Method</div>
            ${(r.method&&r.method.length)?(tierAllows('pro')?`<button onclick="set({cookRecipe:{section:'meals',id:'${r.id}'},cookStep:0});window.scrollTo(0,0);" style="background:var(--accent);border:none;border-radius:8px;color:var(--on-media);font-size:13px;font-weight:bold;padding:8px 14px;cursor:pointer;">👨‍🍳 Start Cooking →</button>`:`<span style="background:var(--card2);border:1px dashed var(--line);border-radius:8px;color:var(--ink-soft);font-size:13px;font-weight:bold;padding:8px 14px;white-space:nowrap;">🔒 Start Cooking — Pro</span>`):''}
          </div>
          ${methodRowsW}
        </div>
        <!-- Goes Well With -->
        ${(r.goesWith&&r.goesWith.length)?`<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:12px;">
          <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;margin-bottom:8px;">❤ Goes Well With</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px;">${r.goesWith.map(g=>{const _lk2=(typeof goesWithLink==='function')?goesWithLink(g):null;return _lk2?`<span onclick="${_lk2}" style="padding:6px 13px;border-radius:16px;border:1px solid var(--accent);color:var(--accent);font-size:14px;font-weight:bold;cursor:pointer;">${g} ›</span>`:`<span style="padding:6px 13px;border-radius:16px;border:1px solid var(--line);color:var(--ink-soft);font-size:14px;">${g}</span>`;}).join('')}</div>
        </div>`:''}
        <!-- Tip -->
        ${r.tip?`<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:12px;">
          <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;margin-bottom:6px;">💡 Tip</div>
          <p style="font-size:13px;color:var(--ink2);line-height:1.6;margin:0;">${r.tip}</p></div>`:''}
        <!-- Did You Know -->
        ${r.didYouKnow?`<div style="background:var(--card);border:1px solid var(--line);border-left:3px solid var(--accent);border-radius:10px;padding:12px;margin-bottom:12px;">
          <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--paprika);text-transform:uppercase;margin-bottom:6px;">💡 Did You Know</div>
          <p style="font-size:13px;color:var(--ink2);line-height:1.6;margin:0;">${r.didYouKnow}</p></div>`:''}
        <!-- Nutrition -->
        ${r.nutrition?`<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:12px;">
          <div style="font-size:11px;font-weight:800;letter-spacing:0.12em;color:var(--green);text-transform:uppercase;margin-bottom:8px;">📊 Nutrition — per serving</div>
          ${nutritionGrid(r.nutrition)}</div>`:''}
        <!-- Storage -->
        ${r.storage?`<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:13px;color:var(--ink-soft);">📦 ${r.storage}</div>`:''}
        ${costW}
        <!-- Save deleted 15 Jul — the heart is the only save -->
        <!-- WhatsApp -->
        <button onclick="window.open('https://wa.me/?text=${_waText}','_blank')" style="width:100%;padding:13px;border-radius:10px;background:var(--card);border:2px solid #25d366;color:#25d366;font-size:13px;cursor:pointer;margin-bottom:12px;">📱 Share Recipe via WhatsApp</button>
        <!-- Back -->
        <button onclick="${backAction}" style="width:100%;padding:14px;border-radius:10px;cursor:pointer;background:var(--accent);border:none;color:var(--on-media);font-size:14px;font-weight:bold;margin-bottom:20px;">← Back</button>
      </div>
    </div>`;
  }

  return `<div style="min-height:100vh;background:#0f0e0c;">
    <div style="position:relative;">
      ${(typeof recipePhoto==='function')?recipePhoto(r.photoName||r.name, r.emoji, 200):''}
      <button onclick="${backAction}" style="position:absolute;top:10px;left:10px;z-index:3;background:rgba(8,4,2,0.65);border:1px solid ${border};border-radius:20px;color:${color};font-size:13px;padding:5px 12px;cursor:pointer;">← Back</button>
      ${_heart}
    </div>
    <div style="padding:0 16px 16px;max-width:600px;margin:0 auto;">
      <h1 style="font-size:22px;font-weight:normal;color:#f5e8cc;margin:6px 0 2px;line-height:1.25;">${r.emoji||'🍽️'} ${dietTag(r.diet)}${(typeof tinzaDisplayName==='function')?tinzaDisplayName(r):r.name}</h1>
      <div style="font-size:13px;color:${color};font-style:italic;margin-bottom:12px;">Full recipe and method</div>

      ${r.feel?`<div style="font-style:italic;color:${color};font-size:13px;text-align:center;line-height:1.5;margin-bottom:14px;">“${r.feel}”</div>`:''}

      ${typeof versionStripHTML==='function'?versionStripHTML(r,color):''}

      <!-- How much to make block -->
      <div style="background:#1a2208;border:2px solid #6a8020;border-radius:12px;padding:14px;margin-bottom:14px;">
        <div style="font-size:13px;letter-spacing:2px;color:#8ab030;text-transform:uppercase;margin-bottom:8px;">🧮 How Much To Make</div>
        <div style="font-size:13px;color:#718933;margin-bottom:10px;">${_bakeP?_bakeUnitLbl:(sv+' '+(sv===1?'person':'people'))}</div>
        <div style="display:flex;align-items:center;gap:12px;">
          <button onclick="const _k=S._budgetActiveRecipe?'budgetPeople':S.moodActiveRecipe?'moodServings':'searchServings';setQuiet({[_k]:${_bakeP?_decW:'Math.max(1,(S[_k]||4)-1)'}})" style="width:36px;height:36px;border-radius:50%;background:#0f1a04;border:2px solid #6a8020;color:#8ab030;font-size:20px;cursor:pointer;">−</button>
          <div style="flex:1;text-align:center;">
            <div style="font-size:32px;font-weight:bold;color:#c8e840;">${_bakeP?_bakeBatches:sv}</div>
            <div style="font-size:13px;color:#718d28;">${_bakeP?(_bakeP.mode==='slice'?('makes '+_bakeBatches+' '+_bakeP.unitWord+(_bakeBatches>1?'s':'')+' · serves '+_bakeUnits+' · 1 '+_bakeP.pieceWord+' each'):('makes '+_bakeBatches+' '+_bakeP.unitWord+(_bakeBatches>1?'s':'')+' · ~'+_bakeUnits+' '+_bakeP.pieceWord+'s')):'people · all quantities scale'}</div>
            ${_softNote?`<div style="margin-top:6px;font-size:12px;color:#718d28;">${_softNote}</div>`:''}
          </div>
          <button onclick="const _k=S._budgetActiveRecipe?'budgetPeople':S.moodActiveRecipe?'moodServings':'searchServings';setQuiet({[_k]:${_bakeP?_incW:'Math.min(500,(S[_k]||4)+1)'}})" style="width:36px;height:36px;border-radius:50%;background:#0f1a04;border:2px solid #6a8020;color:#8ab030;font-size:20px;cursor:pointer;">+</button>
        </div>
        <div style="margin-top:8px;font-size:13px;color:#6c8c23;">${_bakeP?('💡 Bakes come in whole '+_bakeP.unitWord+'s — the dial rounds up so you never bake a fraction.'):'💡 Adjust the number and all ingredients update instantly.'}</div>
      </div>

      ${equipmentContract(r, _bakeP?_bakeUnits:sv, _bakeP?_bakeP.unitWord:null, _bakeBatches)}${equipmentLine(r, _bakeP?_bakeUnits:sv)}
      <!-- Ingredients — bullet style like braai, no tick boxes -->
      <div style="background:${bg};border:1px solid ${border};border-radius:10px;padding:14px;margin-bottom:12px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
          <div style="font-size:13px;letter-spacing:2px;color:${color};text-transform:uppercase;">Ingredients</div>
          <div style="font-size:13px;color:#908066;font-style:italic;">${_bakeP?('for '+_bakeUnitLbl):('scaled for '+sv+' '+(sv===1?'person':'people'))}</div>
        </div>
        ${(r.ingredients||[]).map(i=>{
          if(!i.pp) return `<div style="padding:5px 0;border-bottom:1px solid #1a1810;font-size:13px;color:#8e7c7c;font-style:italic;">• ${i.n} — to taste</div>`;
          const raw=i.pp*_scale, u=i.u||'';
          const ppStr=i.pp+(u==='egg'?' egg':u)+' pp';
          const totalStr=u==='egg'?Math.ceil(raw)+' egg'+(Math.ceil(raw)>1?'s':'')
            :(raw>=1000&&(u==='g'||u==='ml'))?(Math.round(raw/100)/10)+(u==='g'?'kg':'L')
            :Math.round(raw*10)/10+u;
          return `<div style="display:flex;gap:8px;padding:7px 0;border-bottom:1px solid #1a1810;">
            <span style="color:${color};flex-shrink:0;">•</span>
            <span style="font-size:14px;color:#e0d4b8;flex:1;">${(typeof crossLinkFor==='function'&&typeof INGREDIENT_LINKS!=='undefined'&&crossLinkFor(INGREDIENT_LINKS,i.n))?`<span onclick="${crossLinkFor(INGREDIENT_LINKS,i.n)}" style="color:${color};font-weight:bold;cursor:pointer;text-decoration:underline;text-decoration-style:dotted;">${i.n} ↗</span>`:i.n} — <span style="color:#908066;font-size:13px;">${ppStr}</span> · <strong style="color:#f5c842;">${totalStr} total</strong></span>
          </div>`;
        }).join('')}
        ${(r.ingredients||[]).some(i=>/rice|pap|mealie|samp|meat|mince|chicken|beef|lamb|pork|steak|wors|sausage|fish|snoek|bacon|biltong|chop|\brib/i.test(i.n))?`<div style="margin-top:8px;padding-top:6px;border-top:1px solid #1a1810;font-size:13px;color:#8e7c7c;font-style:italic;">📏 Raw/dry weights · Rice+pap grow 3x when cooked · Meat shrinks ~25%</div>`:''}
      </div>

      <!-- Method -->
      <div style="background:${bg};border:1px solid ${border};border-radius:10px;padding:14px;margin-bottom:12px;">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:10px;">
          <div style="font-size:13px;letter-spacing:2px;color:${color};text-transform:uppercase;">Method</div>
          ${(r.method&&r.method.length)?(tierAllows('pro')?`<button onclick="set({cookRecipe:{section:'meals',id:'${r.id}'},cookStep:0});window.scrollTo(0,0);" style="background:${color};border:none;border-radius:8px;color:#fff;font-size:13px;font-weight:bold;padding:8px 14px;cursor:pointer;">👨‍🍳 Start Cooking →</button>`:`<span style="background:var(--card2);border:1px dashed var(--line);border-radius:8px;color:var(--ink-soft);font-size:13px;font-weight:bold;padding:8px 14px;white-space:nowrap;">🔒 Start Cooking — Pro</span>`):''}
        </div>
        ${(r.method||[]).map((step,si)=>{const _sec=(typeof parseStepTime==='function')?parseStepTime(step):0;const _tmr=!_sec?'':(tierAllows('pro')?`<div style="margin-top:7px;"><button onclick="startTimer(${_sec},'Step ${si+1}')" style="display:inline-block;background:#0a0808;border:1px solid ${color};border-radius:6px;color:#f5c842;font-size:13px;font-weight:bold;padding:4px 11px;cursor:pointer;">⏱️ ${(typeof fmtTimerLabel==='function')?fmtTimerLabel(_sec):Math.round(_sec/60)+' min'}</button></div>`:`<div style="margin-top:7px;"><span style="display:inline-block;background:#0a0808;border:1px dashed ${color};border-radius:6px;color:var(--ink-soft);font-size:13px;padding:4px 11px;">⏱️ ${(typeof fmtTimerLabel==='function')?fmtTimerLabel(_sec):Math.round(_sec/60)+' min'} · 🔒 Pro</span></div>`);return `<div style="display:flex;gap:12px;margin-bottom:14px;"><div style="width:24px;height:24px;border-radius:50%;background:#0a0808;border:1px solid ${color};color:${color};font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${si+1}</div><div style="flex:1;"><p style="margin:2px 0 0;font-size:14px;color:#e0d4b8;line-height:1.7;">${step}</p>${_tmr}</div></div>`;}).join('')}
      </div>

      <!-- Goes Well With -->
      ${(r.goesWith&&r.goesWith.length)?`<div style="background:#0a0808;border:1px solid ${border};border-radius:10px;padding:12px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:${color};text-transform:uppercase;margin-bottom:8px;">❤ Goes Well With</div>
        <div style="display:flex;flex-wrap:wrap;gap:6px;">${r.goesWith.map(g=>{const _lk=(typeof goesWithLink==='function')?goesWithLink(g):null;return _lk?`<span onclick="${_lk}" style="padding:6px 13px;border-radius:16px;border:1px solid ${color};color:${color};font-size:13px;font-weight:bold;cursor:pointer;">${g} ›</span>`:`<span style="padding:6px 13px;border-radius:16px;border:1px solid ${border};color:#e0d4b8;font-size:13px;">${g}</span>`;}).join('')}</div>
      </div>`:''}

      <!-- Tip -->
      ${r.tip?`<div style="background:#0a0808;border:1px solid ${border};border-radius:10px;padding:12px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:${color};text-transform:uppercase;margin-bottom:6px;">💡 Tip</div>
        <p style="font-size:13px;color:#e0d4b8;line-height:1.6;margin:0;">${r.tip}</p>
      </div>`:''}

      <!-- Did You Know — the fourth voice (TINZA_DIDYOUKNOW_STANDARD) -->
      ${r.didYouKnow?`<div style="background:#100b06;border:1px solid ${border};border-left:3px solid ${color};border-radius:10px;padding:12px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:${color};text-transform:uppercase;margin-bottom:6px;">💡 Did You Know</div>
        <p style="font-size:13px;color:#e0d4b8;line-height:1.6;margin:0;">${r.didYouKnow}</p>
      </div>`:''}

      <!-- Nutrition -->
      ${r.nutrition?`<div style="background:#0a1008;border:1px solid #1a3020;border-radius:10px;padding:12px;margin-bottom:12px;">
        <div style="font-size:13px;letter-spacing:2px;color:#40a060;text-transform:uppercase;margin-bottom:8px;">📊 Nutrition — per serving</div>
        ${nutritionGrid(r.nutrition)}
      </div>`:''}

      <!-- Storage -->
      ${r.storage?`<div style="background:#0a0808;border:1px solid ${border};border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:13px;color:#718471;">📦 ${r.storage}</div>`:''}

      <!-- Cost estimate -->
      ${_costEstimate}

      <!-- Save deleted 15 Jul — the heart is the only save -->

      <!-- WhatsApp -->
      <button onclick="window.open('https://wa.me/?text=${_waText}','_blank')" style="width:100%;padding:13px;border-radius:10px;background:#0a1a0a;border:2px solid #25d366;color:#25d366;font-size:13px;cursor:pointer;margin-bottom:12px;">📱 Share Recipe via WhatsApp</button>

      <!-- Back button — orange like braai -->
      <button onclick="${backAction}" style="width:100%;padding:14px;border-radius:10px;cursor:pointer;background:${color};border:none;color:#fff;font-size:14px;font-weight:bold;margin-bottom:20px;">← Back</button>
    </div>
  </div>`;
}


// ── UNIVERSAL SECTION PLAN SYSTEM ────────────────────────────────
// planKey = 'wkPlan' | 'mealPlan' | 'moodPlan' | 'budgetPlan'
// item = {id, name, emoji, ingredients:[], serves:1}

function togglePlanItem(planKey, item){
  const plan = S[planKey]||[];
  const exists = plan.some(x=>x.id===item.id);
  if(exists){
    setQuiet({[planKey]: plan.filter(x=>x.id!==item.id)});
  } else {
    setQuiet({[planKey]: [...plan, item]});
  }
}

function isPlanItem(planKey, id){
  return (S[planKey]||[]).some(x=>x.id===id);
}

function packSizeNote(accent){
  accent = accent || '#c0a040';
  return '<div style="background:rgba(255,255,255,0.03);border:1px dashed '+accent+';border-radius:8px;padding:9px 12px;margin-bottom:12px;font-size:14px;color:#e0d4b8;line-height:1.5;">'
    + '\uD83D\uDCA1 <b style="color:'+accent+';">Buying vs cooking:</b> the amounts are what the recipes actually use. In the shop you buy in packs (a 1kg bag of carrots for a 150g need), so you\'ll have a little left over \u2014 the per-person cost is the true cost of what you use, not the whole pack.'
    + '</div>';
}

function buildCombinedShoppingList(plan, people){
  // Combine and deduplicate all ingredients across all plan recipes
  const totals = {};
  plan.forEach(r=>{
    const sv = people||1;
    (r.ingredients||[]).forEach(ing=>{
      if(!ing.pp || !ing.n) return;
      const key = ing.n.toLowerCase().trim();
      const amount = ing.pp * sv;
      if(!totals[key]){
        totals[key] = {n:ing.n, total:0, u:ing.u||''};
      }
      totals[key].total += amount;
    });
  });
  return Object.values(totals).sort((a,b)=>a.n.localeCompare(b.n));
}

function formatAmount(total, u){
  if(!u) return Math.round(total*10)/10+'';
  if((u==='g'||u==='ml') && total>=1000){
    return (Math.round(total/100)/10) + (u==='g'?'kg':'L');
  }
  return (Math.round(total*10)/10) + u;
}

// ── SHARED PLAN ENGINE (migrated 2 Jul 2026) ──────────────────────────
// sectionPlanView now DELEGATES to the shared core.js planView/shoppingView so
// FMF (mealPlan), Budget (budgetPlan) and Just-Feed-Me (moodPlan) all render the
// IDENTICAL two-cost (green food / gold shop-spend), aisle-sorted, pack-rounded
// shopping list. Signature is unchanged, so budget.js and core.js callers are
// untouched — sameness rolls to all three at once (LOCKED §L2).
// (Old buildCombinedShoppingList/formatAmount above are now unused; left in place
//  to keep this edit minimal — flagged for a later cleanup sweep.)
function planDishesFromItems(plan, people, emoji, planKey){
  return (plan||[]).map(function(r){
    // PART I — bakes aggregate by WHOLE batches in the plan/shopping too (BATCH LAW),
    // so the plan cost matches the recipe page (whole cakes, never a fraction). A clean
    // object is passed so the plan item's legacy serves:1 can't hijack the bake yield.
    var _bp = (typeof bakesPortion==='function') ? bakesPortion({cat:r.cat, serves:r.bakeServes, makes:r.bakeMakes}) : null;
    var _mult = _bp ? (Math.max(1, Math.ceil((people||1)/_bp.perBatch)) * _bp.perBatch) : people;
    var ings = (r.ingredients||[]).filter(function(i){ return i && i.pp && i.n; }).map(function(i){
      var u=i.u||'', amt=(i.pp||0)*_mult, unit, a;
      if(u==='kg'){ unit='g';  a=amt*1000; }
      else if(u==='l'){ unit='ml'; a=amt*1000; }
      else if(u==='g'||u==='ml'){ unit=u; a=amt; }
      else { unit='pcs'; a=amt; }                 // egg / count / unitless -> pieces
      return { name:i.n, amt:a, unit:unit, priceName:i.priceName||null };
    });
    var kcalPP = (r.nutrition && r.nutrition.kcal!=null) ? r.nutrition.kcal : null;
    var idJs = String(r.id||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return {
      id:r.id, name:r.name, emoji:(r.emoji||emoji||'\U0001F37D\uFE0F'), kcalPP:kcalPP, guests:people,
      removeJs: planKey ? ("setQuiet({"+planKey+":(S."+planKey+"||[]).filter(function(x){return x.id!=='"+idJs+"';})})") : '',
      lines:[ r.time?('\u23F1\uFE0F '+r.time+' min'):'' ].filter(Boolean),
      ingredients:ings
    };
  });
}
function planShopToggle(name){
  var ch = Object.assign({}, S._planCheckedShop||{});
  ch[name] = !ch[name];
  setQuiet({_planCheckedShop:ch});
}
function planShareShoppingList(){
  if(typeof buildPlanData!=='function' || typeof tierAllows==='function' && !tierAllows('pro')) return;
  var plan   = window._sectionPlanForShare||[];
  var people = window._sectionPlanPeople||1;
  var title  = window._sectionPlanTitle||'My Plan';
  var emoji  = window._sectionPlanEmoji||'\U0001F6D2';
  var data = buildPlanData(planDishesFromItems(plan, people, emoji, ''));
  var fmt = function(it){
    var u = it.buyUnit||it.unit;
    if(u==='pcs') return Math.ceil(it.buyAmt)+(((it.name||'').toLowerCase().indexOf('egg')>-1)?' eggs':' pcs');
    if(it.buyPacks>0){ var sz=it.packSize||(it.buyAmt/it.buyPacks); var szStr=(sz>=1000?(sz/1000)+(u==='ml'?'L':'kg'):sz+(u==='ml'?'ml':'g')); return (it.buyPacks===1?szStr:it.buyPacks+'\u00D7'+szStr); }
    if(u==='ml'||u==='l') return it.buyAmt>=1000?(Math.round(it.buyAmt/100)/10)+'L':Math.round(it.buyAmt)+'ml';
    return it.buyAmt>=1000?(Math.round(it.buyAmt/100)/10)+'kg':Math.round(it.buyAmt)+'g';
  };
  var lines = (data.items||[]).filter(function(it){ return !it.pantry; }).map(function(it){ return '\u2022 '+it.name+': '+fmt(it); }).join('\n');
  var txt = encodeURIComponent(emoji+' '+title+'\n'+people+' '+(people===1?'person':'people')+'\n\n\U0001F6D2 Shopping List:\n'+lines+'\n\nFrom Tinza tinza.netlify.app');
  window.open('https://wa.me/?text='+txt,'_blank');
}
function sectionPlanView(planKey, title, emoji, color, bg, border, people, backAction){
  // stash context for the shared WhatsApp share button (planShareShoppingList)
  window._sectionPlanForShare = S[planKey]||[];
  window._sectionPlanPeople   = people;
  window._sectionPlanTitle    = title;
  window._sectionPlanEmoji    = emoji;
  var svKey = (planKey==='budgetPlan') ? 'budgetPeople' : (planKey==='moodPlan') ? 'moodServings' : 'searchServings';
  return planView({
    header:{ title:emoji+' '+title, emoji:emoji,
      tagline:'Menu \u00B7 shopping list \u00B7 cost for '+people+' '+(people===1?'person':'people'),
      backJs:backAction, backLabel:'\u2190 Back' },
    guests:{ value:people, label:'People', note:'the whole plan scales to this',
      decJs:"set({"+svKey+":Math.max(1,(S."+svKey+"||"+people+")-1)})",
      incJs:"set({"+svKey+":(S."+svKey+"||"+people+")+1})" },
    dishes:  planDishesFromItems(S[planKey]||[], people, emoji, planKey),
    checked: S._planCheckedShop||{},
    toggleFn:'planShopToggle',
    shareJs: 'planShareShoppingList()',
    empty:'Your plan is empty \u2014 open any dish and tap \uFF0B Add to My Plan.'
  });
}

function sectionPlanBtn(planKey, title, emoji, color, bg, people, viewAction){
  const plan = S[planKey]||[];
  if(!plan.length) return '';
  const isPro = tierAllows('pro');
  // Warm branch (FMF): token-driven so the button reads on the parchment page. Non-warm
  // callers (budget · mood) keep their exact colour/bg params + #f5e8cc — byte-identical.
  if((typeof inWarm==='function') && inWarm()){
    if(!isPro) return `<div style="background:var(--card2);border:1px dashed var(--accent);border-radius:10px;padding:12px;margin:10px 0 4px;text-align:center;opacity:0.85;"><div style="font-size:13px;color:var(--accent);">📋 My Plan — <strong>Tinza Pro</strong></div></div>`;
    return `<button onclick="${viewAction}" style="width:100%;padding:14px;margin:10px 0 4px;border-radius:10px;border:1px solid var(--accent);background:var(--card2);color:var(--ink);font-size:14px;font-weight:bold;cursor:pointer;">
    📋 See my ${title} Plan & Shopping List →
    <div style="font-size:13px;color:var(--accent);font-weight:normal;margin-top:3px;">${plan.length} recipe${plan.length!==1?'s':''} · ${people} people</div>
  </button>`;
  }
  if(!isPro) return `<div style="background:${bg};border:1px dashed ${color};border-radius:10px;padding:12px;margin:10px 0 4px;text-align:center;opacity:0.6;"><div style="font-size:13px;color:${color};">📋 My Plan — <strong>Tinza Pro</strong></div></div>`;
  return `<button onclick="${viewAction}" style="width:100%;padding:14px;margin:10px 0 4px;border-radius:10px;border:2px solid ${color};background:${bg};color:#f5e8cc;font-size:14px;cursor:pointer;">
    📋 See my ${title} Plan & Shopping List →
    <div style="font-size:13px;color:${color};margin-top:3px;">${plan.length} recipe${plan.length!==1?'s':''} · ${people} people</div>
  </button>`;
}

// toggleSavedRecipe() DELETED 15 Jul. It wrote S.savedRecipes — in memory only, keyed
